const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '../../ee');
const dist = path.join(__dirname, 'dist');
if (!fs.existsSync(path.join(dist, 'login.html')) || !fs.existsSync(path.join(dist, 'index.html')) || !fs.existsSync(path.join(dist, 'member.html'))) {
  throw new Error('Run npm run build before staging.');
}
const frontend = path.join(root, 'Frontend');
// This directory is solely generated by this script; remove obsolete hashes.
fs.rmSync(frontend, { recursive: true, force: true });
fs.mkdirSync(frontend, { recursive: true });
fs.copyFileSync(path.join(__dirname, 'frontend.htaccess'), path.join(frontend, '.htaccess'));
for (const name of fs.readdirSync(dist)) {
  const source = path.join(dist, name);
  if (fs.statSync(source).isFile()) fs.copyFileSync(source, path.join(frontend, name));
}
// Industry keeps its established URL while referencing the shared build assets.
fs.copyFileSync(path.join(dist, 'index.html'), path.join(root, 'Industry', 'index.html'));
fs.chmodSync(path.join(root, 'Industry', 'index.html'), 0o755);
console.log('Staged Frontend assets and Industry/index.html.');
